from itertools import combinations

def missing_pairs(params, tests):
    missing = []
    for p1, p2 in combinations(sorted(params), 2):
        covered = {(t[p1], t[p2]) for t in tests}
        for v1 in params[p1]:
            for v2 in params[p2]:
                if (v1, v2) not in covered:
                    missing.append((p1, v1, p2, v2))
    return sorted(missing)

