from itertools import combinations, product

def pairwise(params):
    names = list(params)
    def pairs_of(test):
        return {(a, test[a], b, test[b]) for a, b in combinations(names, 2)}
    candidates = [dict(zip(names, vals)) for vals in product(*params.values())]
    uncovered = set()
    for c in candidates:
        uncovered |= pairs_of(c)
    tests = []
    while uncovered:
        best = max(candidates, key=lambda c: len(pairs_of(c) & uncovered))
        tests.append(best)
        uncovered -= pairs_of(best)
    return tests

