from itertools import combinations, product
P = {'os': ['w', 'm', 'l'], 'br': ['c', 'f', 's'], 'lang': ['en', 'de', 'fr'], 'pay': ['card', 'wallet', 'paypal']}
T = pairwise(P)
for a, b in combinations(P, 2):
    for va, vb in product(P[a], P[b]):
        assert any(t[a] == va and t[b] == vb for t in T), (a, va, b, vb)

